/** The request timeout, in SECONDS. */
export function requestTimeout(): number {
  return 30;
}

import { requestTimeout } from "./config";

/** Build a client. `timeoutMs` must be the request timeout in MILLISECONDS. */
export function makeClient(): { timeoutMs: number } {
  return { timeoutMs: requestTimeout() };
}

const USERS: Record<string, { name: string }> = { u1: { name: "Ada" } };

/** Returns undefined when no user has that id. */
export function findUser(id: string): { name: string } | undefined {
  return USERS[id];
}

import { findUser } from "./users";

export function greet(id: string): string {
  return `Hi ${findUser(id).name}`;
}

/** All indices from 0 up to and INCLUDING n. */
export function indices(n: number): number[] {
  const out: number[] = [];
  for (let i = 0; i <= n; i++) out.push(i);
  return out;
}

import { indices } from "./range";

/** Sum of every element of arr. */
export function sumAll(arr: number[]): number {
  let s = 0;
  for (const i of indices(arr.length)) s += arr[i];
  return s;
}

